from maze import task


def _section_title(text: str, index: int) -> str:
    for line in text.splitlines():
        cleaned = line.strip(" #:-")
        if cleaned:
            return cleaned[:72]
    return f"Section {index}"


@task(task_kind="cpu", resources={"cpu_num": 1, "gpu_mem": 0, "io_num": 0})
def resource_mix_split_sections(corpus: str = "", max_sections: str = "7"):
    """Split the corpus into bounded sections for parallel downstream work."""
    try:
        limit = max(2, min(12, int(max_sections)))
    except Exception:
        limit = 7

    paragraphs = [part.strip() for part in corpus.split("\n\n") if part.strip()]
    if len(paragraphs) < 2:
        lines = [line.strip() for line in corpus.splitlines() if line.strip()]
        paragraphs = ["\n".join(lines[i:i + 4]) for i in range(0, len(lines), 4)]
    if not paragraphs:
        paragraphs = ["empty corpus"]

    selected = paragraphs[:limit]
    sections = []
    for index, text in enumerate(selected, start=1):
        sections.append({
            "id": f"s{index:02d}",
            "title": _section_title(text, index),
            "text": text,
            "char_count": len(text),
            "line_count": len(text.splitlines()) or 1,
        })

    return {
        "sections": sections,
        "section_count": len(sections),
        "section_titles": [section["title"] for section in sections],
    }

import math
import re
from collections import Counter

from maze import task


STOP_WORDS = {
    "a", "an", "and", "are", "as", "at", "be", "by", "for", "from", "how",
    "in", "into", "is", "it", "of", "on", "or", "should", "that", "the",
    "this", "to", "what", "when", "with",
}


def _tokens(text: str) -> list[str]:
    return [
        token
        for token in re.findall(r"[A-Za-z][A-Za-z0-9_'-]*", text.lower())
        if token not in STOP_WORDS and len(token) > 2
    ]


@task(task_kind="cpu", resources={"cpu_num": 2, "gpu_mem": 0, "io_num": 0})
def resource_mix_cpu_token_stats(corpus: str = "", sections: list = None):
    """Compute CPU-heavy token counts and per-section densities."""
    sections = sections or []
    tokens = _tokens(corpus)
    counts = Counter(tokens)
    top_terms = [
        {"term": term, "count": count}
        for term, count in counts.most_common(12)
    ]

    densities = []
    for section in sections:
        section_tokens = _tokens(section.get("text", ""))
        char_count = max(1, section.get("char_count") or len(section.get("text", "")) or 1)
        densities.append({
            "section_id": section.get("id"),
            "title": section.get("title"),
            "token_count": len(section_tokens),
            "density": round(len(section_tokens) / math.sqrt(char_count), 4),
        })

    keyword_scores = {
        "cpu": counts.get("cpu", 0),
        "gpu": counts.get("gpu", 0),
        "io": counts.get("io", 0) + counts.get("file", 0) + counts.get("artifact", 0),
        "workflow": counts.get("workflow", 0) + counts.get("task", 0),
    }

    return {
        "token_stats": {
            "total_tokens": len(tokens),
            "unique_tokens": len(counts),
            "lexical_diversity": round(len(counts) / max(1, len(tokens)), 4),
            "keyword_scores": keyword_scores,
        },
        "top_terms": top_terms,
        "section_density": densities,
        "keyword_scores": keyword_scores,
    }

import re

from maze import task


def _tokens(text: str) -> set[str]:
    return set(re.findall(r"[A-Za-z][A-Za-z0-9_'-]*", text.lower()))


@task(task_kind="cpu", resources={"cpu_num": 2, "gpu_mem": 0, "io_num": 0})
def resource_mix_cpu_section_graph(sections: list = None, top_terms: list = None):
    """Build a section similarity graph and rank the most connected sections."""
    sections = sections or []
    important_terms = {item.get("term") for item in (top_terms or []) if item.get("term")}
    token_sets = {
        section.get("id", f"s{index:02d}"): _tokens(section.get("text", ""))
        for index, section in enumerate(sections, start=1)
    }

    edges = []
    for left_index, left in enumerate(sections):
        left_id = left.get("id", f"s{left_index + 1:02d}")
        for right in sections[left_index + 1:]:
            right_id = right.get("id")
            overlap = token_sets[left_id] & token_sets.get(right_id, set())
            if important_terms:
                overlap = overlap | ((token_sets[left_id] & important_terms) & (token_sets.get(right_id, set()) & important_terms))
            union_size = max(1, len(token_sets[left_id] | token_sets.get(right_id, set())))
            weight = round(len(overlap) / union_size, 4)
            if weight > 0:
                edges.append({
                    "source": left_id,
                    "target": right_id,
                    "weight": weight,
                    "shared_terms": sorted(overlap)[:8],
                })

    degree = {section.get("id", f"s{index:02d}"): 0.0 for index, section in enumerate(sections, start=1)}
    for edge in edges:
        degree[edge["source"]] = degree.get(edge["source"], 0.0) + edge["weight"]
        degree[edge["target"]] = degree.get(edge["target"], 0.0) + edge["weight"]

    ranked_sections = sorted([
        {
            "section_id": section.get("id", f"s{index:02d}"),
            "title": section.get("title", ""),
            "score": round(degree.get(section.get("id", f"s{index:02d}"), 0.0) + section.get("char_count", 0) / 1000, 4),
        }
        for index, section in enumerate(sections, start=1)
    ], key=lambda item: item["score"], reverse=True)

    return {
        "graph_stats": {
            "node_count": len(sections),
            "edge_count": len(edges),
            "max_rank_score": ranked_sections[0]["score"] if ranked_sections else 0,
        },
        "ranked_sections": ranked_sections,
        "graph_edges": edges,
    }

